-- Administratör som undervisar (Users.teaches), del 4: krisläge, mentor och rapporteringsgrad (20270219090000_en_undervisande_administrator_svarar_i_larmet_ar_mentor_och_rapporterar), PRODUKTION, EFTER migreringen, EFTER C1 (20270218090000; produktionens ordning, granskning 327).
-- Bara läsning: en SELECT per rad, kolumnerna check, got, expected, ok. Text som ordnas har COLLATE "C" (produktionen sorterar en_US, provdatabaserna C).
-- Migreringens sha256: a7e634696ce8c9716505f82cf39d0e7039c1b63ffc8d069ce34d68f4cae96de6
-- Kör som ägaren: psql -X -tA -F '|' -v ON_ERROR_STOP=1 -f <fil>  (valfritt med PGOPTIONS='-c default_transaction_read_only=on'). Förväntat: varje rad slutar på |t.
-- Rader med expected 'jämför med före/efter' är räknetal och fingeravtryck som alltid är ok = true: spara got och jämför med motsvarande rad i den andra filen.
-- Förväntade värden är lästa ur engångsdatabaser på Postgres 17 (main 202a4a9e, 220 migreringar). Produktionens egna siffror (serverversion, antal och fingeravtryck av migrationsrader) sätts efter
-- produktionens rader: F04-F06 och E03-E04 beror på vilka lägre migreringar som är körda före den här (till exempel 20270218090000, C1).
-- KÖR INTE MIGRERINGEN MEDAN ETT LARM ÄR ÖPPET: raden F09 ska vara 0.
-- Är en rad röd: stanna och läs got. En funktion eller policy vars md5 inte är den förväntade har ändrats av en annan gren sedan main 202a4a9e: migreringen patchar texten ur katalogen och stoppar själv (utan att något ändras).
SELECT 'E01 migreringen är körd och fullbordad' AS check, g AS got, '1' AS expected, coalesce(g = '1', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE migration_name = '20270219090000_en_undervisande_administrator_svarar_i_larmet_ar_mentor_och_rapporterar' AND finished_at IS NOT NULL AND rolled_back_at IS NULL)::text AS g) s;
SELECT 'E02 ingen migrering är ofullbordad eller återrullad' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE finished_at IS NULL OR rolled_back_at IS NOT NULL)::text AS g) s;
SELECT 'E03 antal körda migreringar (mains + 1; samordnaren sätter produktionens egen)' AS check, g AS got, '222' AS expected, coalesce(g = '222', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL)::text AS g) s;
